style.css:
@-moz-document domain("facebook.com") {
/*==========================
  FACEBOOK PINK 2026
===========================*/

:root{

    --pink1:#ffe6f2;
    --pink2:#ffd4e8;
    --pink3:#ffc0dd;
    --pink4:#ff8dbb;
    --pink5:#ff5fa3;

    --text:#7c2b58;
    --white:#ffffff;

    --primary-background:var(--pink1)!important;
    --secondary-background:var(--pink2)!important;
    --card-background:#fff5fa!important;
    --comment-background:#ffeaf3!important;
    --wash:#ffe6f2!important;
    --hover-overlay:rgba(255,105,180,.12)!important;

}

/*==========================
FONDO
===========================*/

html,
body{
    background:var(--pink1)!important;
}

body{
    background-image:
    radial-gradient(circle at top left,#ffffff55,transparent 45%),
    radial-gradient(circle at bottom right,#ffb6d540,transparent 40%);
}

/*==========================
HEADER
===========================*/

div[role="banner"]{
    background:#ffb8d4!important;
    border-bottom:1px solid #ff9ec6!important;
}

/*==========================
PUBLICACIONES
===========================*/

div[role="article"]{

    background:#fff7fb!important;


    box-shadow:
    0 8px 30px rgba(255,120,180,.12)!important;

}



/*==========================
BOTONES
===========================*/

button{

    background:#ff7db5!important;

    color:white!important;

}

button:hover{

    background:#ff5fa3!important;

}

/*==========================
LINKS
===========================*/

a{

    color:#cc2f7d!important;

}

a:hover{

    color:#ff3b92!important;

}

/*==========================
INPUTS
===========================*/

input,
textarea{

    background:#fff8fc!important;

    color:#6b2450!important;
}



/*==========================
SCROLL
===========================*/

::-webkit-scrollbar{

    width:12px;

}

::-webkit-scrollbar-track{

    background:#ffe6f2;

}

::-webkit-scrollbar-thumb{

    background:#ff88bb;

    border-radius:50px;

}

::-webkit-scrollbar-thumb:hover{

    background:#ff5fa3;

}


/*==========================
HOVER TARJETAS
===========================*/

div[role="article"]:hover{


    box-shadow:

    0 12px 36px rgba(255,120,180,.22)!important;

}

/*==========================
MENÚS
===========================*/

[role="navigation"]{

    background:#fff0f7!important;

}

[role="complementary"]{

    background:#fff0f7!important;

}

/*==========================
SEPARADORES
===========================*/

hr{

    border-color:#ffc4de!important;

}

/*==========================
SELECCIÓN
===========================*/

::selection{

    background:#ff90bf;

    color:white;

}

/*==========================
 logo tipo 
===========================*/

a[aria-label="Facebook"] svg path:first-child{
    fill:#ffd1e6!important;
}

a[aria-label="Facebook"] svg path:last-child{
    fill:#ff2f8d!important;
}
}
